#include <iostream>
using namespace std;

int fa[100001];

void init(int n) { for (int i = 1; i <= n; i++) fa[i] = i; }

int find(int x) {
    if (fa[x] == x) return x;
    return find(fa[x]);
}

void unite(int x, int y) {
    fa[find(x)] = find(y);
}

int main() {
    int n, m;
    cin >> n >> m;
    init(n);
    for (int i = 0; i < m; i++) {
        int op, x, y;
        cin >> op >> x >> y;
        if (op == 1) unite(x, y);
        else cout << (find(x) == find(y) ? "Yes" : "No") << endl;
    }
    return 0;
}

int find(int x) {
    if (fa[x] == x) return x;
    fa[x] = find(fa[x]);
    return fa[x];
}

int fa[100001], sz[100001];
void init(int n) {
    for (int i = 1; i <= n; i++) { fa[i] = i; sz[i] = 1; }
}
void unite(int x, int y) {
    int rx = find(x), ry = find(y);
    if (rx == ry) return;
    if (sz[rx] < sz[ry]) { fa[rx] = ry; sz[ry] += sz[rx]; }
    else { fa[ry] = rx; sz[rx] += sz[ry]; }
}
